arguments.command:
D=/data/current.db; sqlite3 $D "
select ce.change_id, k.kind_code, ce.service_id, ce.pool_id, ce.effective_at_ms, ce.before_json, ce.after_json, ce.change_note from change_events ce join change_kinds k on k.kind_id=ce.kind_id where ce.service_id=2 and ce.effective_at_ms between 1778148000000 and 1778155200000;
select * from route_assignments where route_id in (3,4,8);"

